detail.sass:
@use 'tremplin/scss/drawer' with (
  $drawer-tokens: (
    --trm-drawer-height: 22rem,
    --trm-drawer-border-radius: 1rem
  )
);

// Separate runtime fallback, not a Sass-map key:
.drawer-sheet { --trm-drawer-sheet-width: 42rem; }

javascript:
import Drawer from 'tremplin/drawer'

const element = document.querySelector('#actions')
const instance = Drawer.getOrCreateInstance(element)

applicationJavascript:
document.addEventListener('DOMContentLoaded', () => {
  // Application initial-focus policy after Drawer becomes visible.
  document.querySelectorAll('.docs-example dialog.drawer-sheet').forEach(root => {
    root.addEventListener('shown.trm.drawer', () => root.querySelector('[autofocus]')?.focus())
  })
})

